import React from 'react';
import styles from './DetailPanel.module.css';
import { useApp } from '../../context/AppContext';
import { CalendarEvent, Category } from '../../types';
import { fmtDisplayTime, MONTH_SHORT } from '../../utils/dateUtils';

// ─── Helpers ──────────────────────────────────────────────────────────────────

function getCategoryInfo(event: CalendarEvent, categories: Category[]) {
  const cat = categories.find(c => c.id === event.category);
  return {
    name:  cat?.name  || 'Uncategorized',
    icon:  cat?.icon  || '🏷️',
    color: cat?.color || '#888',
  };
}

function hexToRgba(hex: string, alpha: number) {
  const h = hex.replace('#', '');
  const r = parseInt(h.slice(0, 2), 16);
  const g = parseInt(h.slice(2, 4), 16);
  const b = parseInt(h.slice(4, 6), 16);
  return `rgba(${r},${g},${b},${alpha})`;
}

function formatDate(dateStr: string): string {
  const [y, m, d] = dateStr.split('-').map(Number);
  const date = new Date(y, m - 1, d);
  return `${MONTH_SHORT[date.getMonth()]} ${date.getDate()}, ${date.getFullYear()}`;
}

// ─── Subtask row (interactive — check off without opening modal) ───────────────

function SubtaskItem({
  id, text, done, eventId,
}: { id: string; text: string; done: boolean; eventId: string }) {
  const { state, dispatch } = useApp();

  const toggle = () => {
    const ev = state.events.find(e => e.id === eventId);
    if (!ev) return;
    dispatch({
      type: 'UPDATE_EVENT',
      payload: {
        ...ev,
        subtasks: ev.subtasks.map(s => s.id === id ? { ...s, done: !s.done } : s),
      },
    });
  };

  return (
    <div className={styles.subtaskRow}>
      <button
        className={`${styles.subtaskCheck} ${done ? styles.subtaskCheckDone : ''}`}
        onClick={toggle}
        type="button"
        aria-label={done ? 'Mark incomplete' : 'Mark complete'}
      >
        {done && <span className={styles.checkmark}>✓</span>}
      </button>
      <span className={`${styles.subtaskText} ${done ? styles.subtaskTextDone : ''}`}>
        {text}
      </span>
    </div>
  );
}

// ─── Main panel ───────────────────────────────────────────────────────────────

export default function DetailPanel() {
  const { state, dispatch, openEditEvent } = useApp();

  const selectedEvent = state.events.find(e => e.id === state.selectedEventId);
  const { categories } = state;

  const close = () => dispatch({ type: 'SELECT_EVENT', payload: null });

  // ── Empty state ──────────────────────────────────────────────────────────────
  if (!selectedEvent) {
    return (
      <aside className={styles.detail}>
        <div className={styles.empty}>
          <div className={styles.emptyIcon}>🗓</div>
          <div className={styles.emptyText}>Select an event to see details</div>
        </div>
      </aside>
    );
  }

  const cat       = getCategoryInfo(selectedEvent, categories);
  const doneCount = selectedEvent.subtasks.filter(s => s.done).length;
  const total     = selectedEvent.subtasks.length;

  return (
    <aside className={styles.detail}>

      {/* ── Header ─────────────────────────────────────────────────────────── */}
      <div
        className={styles.header}
        style={{ borderBottom: `3px solid ${cat.color}` }}
      >
        <div
          className={styles.colorSwatch}
          style={{
            background:  hexToRgba(selectedEvent.color, 0.15),
            borderColor: selectedEvent.color,
          }}
        >
          <div
            className={styles.colorSwatchInner}
            style={{ background: selectedEvent.color }}
          />
        </div>

        <div className={styles.headerText}>
          <div className={styles.categoryBadge}>
            <span>{cat.icon}</span>
            <span>{cat.name}</span>
          </div>
          <div className={styles.eventTitle} style={{ textDecoration: selectedEvent.completed ? 'line-through' : 'none' }}>
            {selectedEvent.title} {selectedEvent.completed && <span className={styles.completedMark}>✓</span>}
          </div>

        </div>


      </div>

      {/* ── Body ───────────────────────────────────────────────────────────── */}
      <div className={styles.body}>

        {/* Completed banner */}
        {selectedEvent.completed && (
          <div className={styles.completedBanner}>
            <span>✓</span> Completed
          </div>
        )}

        {/* Date + time */}
        <div className={styles.section}>
          <div className={styles.label}>When</div>
          <div className={styles.metaRow}>
            <div className={styles.metaChip}>
              <span className={styles.metaChipIcon}>📅</span>
              {formatDate(selectedEvent.date)}
            </div>
            <div className={styles.metaChip}>
              <span className={styles.metaChipIcon}>🕐</span>
              {fmtDisplayTime(selectedEvent.start)}
              {selectedEvent.end && <> – {fmtDisplayTime(selectedEvent.end)}</>}
            </div>
          </div>
        </div>

        {/* Notes */}
        {selectedEvent.details ? (
          <div className={styles.section}>
            <div className={styles.label}>Notes</div>
            <div className={styles.notes}>{selectedEvent.details}</div>
          </div>
        ) : null}

        {/* Subtasks */}
        {total > 0 && (
          <div className={styles.section}>
            <div className={styles.label}>
              Subtasks
              <span className={styles.subtaskProgress}>
                {' '}{doneCount}/{total}
              </span>
            </div>
            <div className={styles.subtaskList}>
              {selectedEvent.subtasks.map(s => (
                <SubtaskItem
                  key={s.id}
                  id={s.id}
                  text={s.text}
                  done={s.done}
                  eventId={selectedEvent.id}
                />
              ))}
            </div>
          </div>
        )}

      </div>

      {/* ── Footer ─────────────────────────────────────────────────────────── */}
      <div className={styles.footer}>
        <button
          className={styles.editBtn}
          style={{ background: selectedEvent.color }}
          onClick={() => openEditEvent(selectedEvent)}
        >
          Edit event
        </button>
        <button className={styles.closeFooterBtn} onClick={close}>
          Close
        </button>
      </div>

    </aside>
  );
}
